import React, { useRef, useEffect, useCallback, useState } from 'react';

/**
 * SAP S/4HANA Public Cloud — Adobe Form Wizard v5.11 (+ in-app User Guide & Demo Video)
 * React component wrapper for AI BOT integration.
 *
 * Props:
 *   onSendPrompt(text: string) — called when user clicks "Send task to Claude"
 *   style   — optional iframe style overrides
 *   className — optional CSS class
 *   height  — iframe height (default '860px')
 *
 * Usage:
 *   <SAPFormWizard onSendPrompt={(msg) => chatbot.send(msg)} />
 */

// Full wizard HTML (UTF-8, base64-encoded to avoid template-literal conflicts)
const _WIZARD_B64 = '';

function _decodeWizard() {
  try {
    // Inject postMessage bridge so sendPrompt works inside the iframe
    const raw = atob(_WIZARD_B64);
    const html = decodeURIComponent(
      raw.split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join('')
    );
    // Built by concatenation (no template literals, no literal script tags) so the
    // file survives copy/paste and is never mis-parsed as JSX.
    const bridgeJs =
      'window.sendPrompt = function(text) {' +
      "window.parent.postMessage({ type: 'SAP_WIZARD_PROMPT', text: text }, '*');" +
      '};';
    const bridge = '<' + 'script>' + bridgeJs + '<' + '/script>';
    return html.replace('<' + '/head>', bridge + '<' + '/head>');
  } catch (e) {
    return '<p style="font-family:sans-serif;padding:20px;color:red">Failed to decode wizard: ' + e.message + '</p>';
  }
}

const WIZARD_SRCDOC = _decodeWizard();

// ── Model transport (auto) — aligned with the Project Charter Agent ───────────
// Claude artifact / non-localhost → "sandbox" (call the API directly; runtime supplies auth).
// localhost → "backend" (route through your own streaming POST /api/messages proxy).
const BACKEND_URL = "http://localhost:8000";
const HOST = (typeof window !== "undefined" && window.location && window.location.hostname) || "";
const IS_LOCAL = /^(localhost|127\.0\.0\.1|0\.0\.0\.0|\[?::1\]?)$/i.test(HOST);
const MODEL_TRANSPORT_OVERRIDE = "";          // "" = auto · or "sandbox" | "backend" | "direct"
const MODEL_TRANSPORT = MODEL_TRANSPORT_OVERRIDE || (IS_LOCAL ? "backend" : "sandbox");
const API = MODEL_TRANSPORT === "backend"
  ? `${BACKEND_URL}/api/messages`
  : "https://api.anthropic.com/v1/messages";

// Streaming model call (same pattern as the Charter Agent). Calls onDelta with the growing text.
async function callModel(text, onDelta, signal) {
  const body = JSON.stringify({
    model: "claude-sonnet-4-6",
    max_tokens: 4000,
    temperature: 0.3,
    system: "You are an expert assistant for SAP S/4HANA Public Cloud Adobe Forms / Adobe LiveCycle form design. Help the user with the form task they describe: explain steps, generate the requested content, and give clear, accurate SAP-aligned guidance.",
    messages: [{ role: "user", content: text }],
    stream: true,
  });
  const headers = { "Content-Type": "application/json" };
  if (MODEL_TRANSPORT === "direct") {
    headers["anthropic-version"] = "2023-06-01";
    headers["anthropic-dangerous-direct-browser-access"] = "true";
  }
  const res = await fetch(API, { method: "POST", headers, body, signal });
  if (!res.ok) {
    let d = ""; try { const j = await res.json(); d = (j.error && j.error.message) || ""; } catch (e) {}
    throw new Error("HTTP " + res.status + (d ? ": " + d : ""));
  }
  const ctype = (res.headers.get("content-type") || "").toLowerCase();
  if (!ctype.includes("event-stream")) {
    const j = await res.json();
    const t = (j.content || []).map((b) => (b.type === "text" ? b.text : "")).join("");
    onDelta && onDelta(t); return t;
  }
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let buf = "", full = "";
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    let nl;
    while ((nl = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, nl); buf = buf.slice(nl + 1);
      if (!line.startsWith("data: ")) continue;
      const p = line.slice(6).trim();
      if (p === "[DONE]") continue;
      try {
        const ev = JSON.parse(p);
        if (ev.type === "content_block_delta" && ev.delta && ev.delta.type === "text_delta") {
          full += ev.delta.text; onDelta && onDelta(full);
        }
      } catch (e) {}
    }
  }
  return full;
}

const _btn = { background: "rgba(255,255,255,0.16)", color: "#fff", border: "1px solid rgba(255,255,255,0.4)", borderRadius: 7, padding: "3px 10px", fontSize: 12, fontWeight: 700, cursor: "pointer" };

export default function SAPFormWizard({ onSendPrompt, style, className, height = '860px' }) {
  const iframeRef = useRef(null);
  const onSendPromptRef = useRef(onSendPrompt);
  const abortRef = useRef(null);
  const [result, setResult] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [panelOpen, setPanelOpen] = useState(false);
  const [backendStatus, setBackendStatus] = useState(MODEL_TRANSPORT === "backend" ? "checking" : "skipped");

  useEffect(() => { onSendPromptRef.current = onSendPrompt; }, [onSendPrompt]);

  // Health check on load (aligned): if in backend mode, confirm the server is reachable.
  useEffect(() => {
    if (MODEL_TRANSPORT !== "backend") return;
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 4000);
    fetch(API, { method: "GET", signal: ctrl.signal })
      .then(() => setBackendStatus("up"))
      .catch(() => setBackendStatus("down"))
      .finally(() => clearTimeout(t));
  }, []);

  // When the wizard sends a prompt: if a host provided onSendPrompt, hand off to it;
  // otherwise CALL THE MODEL OURSELVES and stream the reply into the result panel.
  const runPrompt = useCallback(async (text) => {
    if (onSendPromptRef.current) { onSendPromptRef.current(text); return; }
    setPanelOpen(true); setBusy(true); setError(""); setResult("");
    try {
      abortRef.current = new AbortController();
      await callModel(text, (partial) => setResult(partial), abortRef.current.signal);
    } catch (e) {
      if (e && e.name === "AbortError") { /* user stopped */ }
      else setError((e && e.message) || "Request failed");
    } finally { setBusy(false); }
  }, []);

  useEffect(() => {
    const handler = (event) => {
      if (event.data && event.data.type === 'SAP_WIZARD_PROMPT') { runPrompt(event.data.text); }
      if (event.data && event.data.type === 'SAP_WIZARD_OPEN_URL' &&
          typeof event.data.url === 'string' && event.data.url.indexOf('https://') === 0) {
        try { window.open(event.data.url, '_blank', 'noopener,noreferrer'); } catch (e) {}
      }
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, [runPrompt]);

  const onLoad = useCallback(() => {
    try {
      const win = iframeRef.current && iframeRef.current.contentWindow;
      if (win) { win.sendPrompt = (text) => runPrompt(text); }
    } catch (e) {}
  }, [runPrompt]);

  return (
    <div style={{ position: 'relative', width: '100%', ...style }} className={className}>
      {backendStatus === 'down' && (
        <div style={{ background: '#FFF7E6', color: '#8A4D00', border: '1px solid #B4690E', borderRadius: 8, padding: '8px 12px', fontSize: 13, marginBottom: 8 }}>
          ⚠ Can't reach the model backend at <code style={{ fontFamily: 'monospace' }}>{API}</code>. Start your server (streaming <code style={{ fontFamily: 'monospace' }}>POST /api/messages</code>), or set <code style={{ fontFamily: 'monospace' }}>MODEL_TRANSPORT_OVERRIDE = "direct"</code>.
        </div>
      )}

      <iframe
        ref={iframeRef}
        srcDoc={WIZARD_SRCDOC}
        onLoad={onLoad}
        title="SAP S/4HANA Adobe Form Wizard"
        sandbox="allow-scripts allow-same-origin allow-downloads allow-modals allow-forms allow-popups allow-popups-to-escape-sandbox"
        style={{ width: '100%', height: height, border: 'none', display: 'block' }}
      />

      {panelOpen && (
        <div style={{ position: 'fixed', right: 16, bottom: 16, width: 'min(520px, 92vw)', maxHeight: '70vh', background: '#fff', border: '1px solid #ddd', borderRadius: 12, boxShadow: '0 16px 50px rgba(0,0,0,0.28)', display: 'flex', flexDirection: 'column', zIndex: 1000 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 14px', background: 'linear-gradient(90deg,#4A1D7A,#7A2BB8)', color: '#fff', borderTopLeftRadius: 12, borderTopRightRadius: 12 }}>
            <span style={{ fontWeight: 700, fontSize: 14 }}>{busy ? 'Claude is working…' : 'Claude'}</span>
            <div style={{ display: 'flex', gap: 8 }}>
              {busy && <button onClick={() => abortRef.current && abortRef.current.abort()} style={_btn}>Stop</button>}
              <button onClick={() => setPanelOpen(false)} style={_btn}>✕</button>
            </div>
          </div>
          <div style={{ padding: '12px 14px', overflowY: 'auto', whiteSpace: 'pre-wrap', fontSize: 13.5, lineHeight: 1.5, color: '#1a1a1a' }}>
            {error ? <span style={{ color: '#b3261e' }}>{error}</span> : (result || (busy ? '…' : ''))}
          </div>
        </div>
      )}
    </div>
  );
}
